import React, { useState, useRef, useEffect, useCallback } from 'react';

interface ManualCropProps {
  imageSrc: string;
  aspectRatio: number; // width / height
  onCrop: (croppedImage: string) => void;
  onCancel: () => void;
  language?: 'vi' | 'en';
}

const ManualCrop: React.FC<ManualCropProps> = ({ imageSrc, aspectRatio, onCrop, onCancel, language = 'vi' }) => {
  const [imgLoaded, setImgLoaded] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);
  const cropBoxRef = useRef<{ x: number, y: number, w: number, h: number }>({ x: 10, y: 10, w: 80, h: 80 });
  const [cropBox, setCropBox] = useState({ x: 10, y: 10, w: 80, h: 80 }); // Percentage based

  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const dragStart = useRef({ x: 0, y: 0, initialX: 0, initialY: 0 });

  const initCropBox = useCallback(() => {
    if (!imgRef.current) return;
    const imgW = imgRef.current.width;
    const imgH = imgRef.current.height;
    const imgRatio = imgW / imgH;

    let w, h;
    if (imgRatio > aspectRatio) {
      // Image wider than target
      h = 80; // 80% of height
      w = (h * aspectRatio) / imgRatio;
    } else {
      // Image taller than target
      w = 80; // 80% of width
      h = (w / aspectRatio) * imgRatio;
    }

    const x = (100 - w) / 2;
    const y = (100 - h) / 2;

    setCropBox({ x, y, w, h });
    cropBoxRef.current = { x, y, w, h };
  }, [aspectRatio]);

  useEffect(() => {
    if (imgLoaded) initCropBox();
  }, [imgLoaded, initCropBox]);

  const handleDragStart = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    setIsDragging(true);
    dragStart.current = { x: clientX, y: clientY, initialX: cropBox.x, initialY: cropBox.y };
  };

  const handleResizeStart = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    setIsResizing(true);
    dragStart.current = { x: clientX, y: clientY, initialX: cropBox.w, initialY: cropBox.h };
  };

  const handleMove = useCallback((e: MouseEvent | TouchEvent) => {
    if (!isDragging && !isResizing) return;
    if (!containerRef.current) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    const rect = containerRef.current.getBoundingClientRect();

    const deltaX = ((clientX - dragStart.current.x) / rect.width) * 100;
    const deltaY = ((clientY - dragStart.current.y) / rect.height) * 100;

    if (isDragging) {
      let newX = Math.max(0, Math.min(dragStart.current.initialX + deltaX, 100 - cropBox.w));
      let newY = Math.max(0, Math.min(dragStart.current.initialY + deltaY, 100 - cropBox.h));
      setCropBox(prev => ({ ...prev, x: newX, y: newY }));
    } else if (isResizing) {
      // Resizing from bottom right corner, maintaining aspect ratio
      const imgW = imgRef.current?.width || 1;
      const imgH = imgRef.current?.height || 1;
      const imgRatio = imgW / imgH;

      let newW = Math.max(10, Math.min(dragStart.current.initialX + deltaX, 100 - cropBox.x));
      let newH = (newW / aspectRatio) * imgRatio;

      // Check height bounds
      if (cropBox.y + newH > 100) {
        newH = 100 - cropBox.y;
        newW = (newH * aspectRatio) / imgRatio;
      }

      setCropBox(prev => ({ ...prev, w: newW, h: newH }));
    }
  }, [isDragging, isResizing, aspectRatio, cropBox.x, cropBox.y, cropBox.w, cropBox.h]);

  const handleEnd = useCallback(() => {
    setIsDragging(false);
    setIsResizing(false);
  }, []);

  useEffect(() => {
    window.addEventListener('mousemove', handleMove);
    window.addEventListener('mouseup', handleEnd);
    window.addEventListener('touchmove', handleMove);
    window.addEventListener('touchend', handleEnd);
    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [handleMove, handleEnd]);

  const executeCrop = () => {
    if (!imgRef.current) return;
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = imgRef.current;
    const realW = img.naturalWidth;
    const realH = img.naturalHeight;

    const cropX = (cropBox.x / 100) * realW;
    const cropY = (cropBox.y / 100) * realH;
    const cropW = (cropBox.w / 100) * realW;
    const cropH = (cropBox.h / 100) * realH;

    canvas.width = cropW;
    canvas.height = cropH;
    ctx.drawImage(img, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH);

    onCrop(canvas.toDataURL('image/jpeg', 1.0));
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-xl flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-2xl flex flex-col gap-6">
        <div className="flex justify-between items-center text-white">
          <div>
            <h2 className="text-xl font-black uppercase tracking-tight">{language === 'vi' ? 'Cắt ảnh thủ công' : 'Manual Crop'}</h2>
            <p className="text-xs text-gray-400 font-medium">{language === 'vi' ? 'Điều chỉnh khung hình để có tỉ lệ mặt chuẩn nhất' : 'Adjust the frame for perfect head proportions'}</p>
          </div>
          <button onClick={onCancel} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
          </button>
        </div>

        <div 
          ref={containerRef}
          className="relative bg-gray-900 rounded-lg overflow-hidden border border-white/10 mx-auto select-none touch-none"
          style={{ maxWidth: '100%', maxHeight: '70vh' }}
        >
          <img 
            ref={imgRef}
            src={imageSrc} 
            className="block max-w-full h-auto opacity-50" 
            onLoad={() => setImgLoaded(true)}
            onDragStart={(e) => e.preventDefault()}
          />

          {imgLoaded && (
            <div 
              className="absolute border-2 border-brand-500 shadow-[0_0_20px_rgba(59,130,246,0.5)] cursor-move"
              style={{
                left: `${cropBox.x}%`,
                top: `${cropBox.y}%`,
                width: `${cropBox.w}%`,
                height: `${cropBox.h}%`,
                backgroundImage: `url(${imageSrc})`,
                backgroundPosition: `${(cropBox.x / (100 - cropBox.w)) * 100}% ${(cropBox.y / (100 - cropBox.h)) * 100}%`,
                backgroundSize: `${100 / (cropBox.w / 100)}% ${100 / (cropBox.h / 100)}%`,
                backgroundRepeat: 'no-repeat'
              }}
              onMouseDown={handleDragStart}
              onTouchStart={handleDragStart}
            >
              {/* Guides */}
              <div className="absolute inset-0 pointer-events-none grid grid-cols-3 grid-rows-3 opacity-30">
                <div className="border-r border-b border-white"></div>
                <div className="border-r border-b border-white"></div>
                <div className="border-b border-white"></div>
                <div className="border-r border-b border-white"></div>
                <div className="border-r border-b border-white"></div>
                <div className="border-b border-white"></div>
                <div className="border-r border-white"></div>
                <div className="border-r border-white"></div>
                <div></div>
              </div>

              {/* Resize Handle */}
              <div 
                className="absolute bottom-[-10px] right-[-10px] w-6 h-6 bg-brand-500 rounded-full border-2 border-white cursor-nwse-resize flex items-center justify-center shadow-lg"
                onMouseDown={handleResizeStart}
                onTouchStart={handleResizeStart}
              >
                <div className="w-2 h-2 border-r-2 border-b-2 border-white transform rotate-45 mb-0.5 mr-0.5"></div>
              </div>
            </div>
          )}
        </div>

        <div className="flex gap-4">
          <button onClick={onCancel} className="flex-1 py-4 bg-gray-800 text-white rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95 transition-all">
            {language === 'vi' ? 'Hủy bỏ' : 'Cancel'}
          </button>
          <button onClick={executeCrop} className="flex-[2] py-4 bg-brand-600 hover:bg-brand-700 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-brand-500/30 active:scale-95 transition-all">
            {language === 'vi' ? 'Xác nhận Cắt' : 'Confirm Crop'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ManualCrop;

