                 onClick={() => setActiveTab(tab.id as any)} 
                 className={`flex-1 flex flex-col items-center py-2.5 rounded-xl transition-all active:scale-95 min-w-[60px] ${
                    activeTab === tab.id 
                    ? 'bg-white dark:bg-gray-700 text-brand-700 dark:text-brand-300 shadow-lg' 
