        {/* Actions Footer */}
        <div className="p-4 md:p-6 border-t border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 space-y-3 shrink-0">
          {hasPendingAiChanges && (
            <button onClick={handleApplyAiChanges} disabled={isProcessing} className="w-full py-4 bg-brand-600 hover:bg-brand-700 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-brand-500/30 active:scale-95 disabled:opacity-50 flex items-center justify-center gap-3">
