export default EditorCropTab;

import React, { useState, useRef, useEffect, useCallback } from 'react';

interface ManualCropProps {
  imageSrc: string;
  aspectRatio: number; // width / height
  onCrop: (croppedImage: string) => void;
  onCancel: () => void;
  language?: 'vi' | 'en';
}

const ManualCrop: React.FC<ManualCropProps> = ({ imageSrc, aspectRatio, onCrop, onCancel, language = 'vi' }) => {
  const [imgLoaded, setImgLoaded] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);

  // CropBox tính theo % (0-100)
  const [cropBox, setCropBox] = useState({ x: 10, y: 10, w: 80, h: 80 }); 

  // Trạng thái thao tác
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [isDrawing, setIsDrawing] = useState(false);

  const dragStart = useRef({ x: 0, y: 0, initialX: 0, initialY: 0, containerRect: { left: 0, top: 0, width: 0, height: 0 } });

  const initCropBox = useCallback(() => {
    if (!imgRef.current) return;
    const imgW = imgRef.current.width;
    const imgH = imgRef.current.height;
    const imgRatio = imgW / imgH;

    let w, h;
    if (imgRatio > aspectRatio) {
      h = 70;
      w = (h * aspectRatio) / imgRatio;
    } else {
      w = 70;
      h = (w / aspectRatio) * imgRatio;
    }

    setCropBox({ x: (100 - w) / 2, y: (100 - h) / 2, w, h });
  }, [aspectRatio]);

  useEffect(() => {
    if (imgLoaded) initCropBox();
  }, [imgLoaded, initCropBox]);

  // Bắt đầu di chuyển khung hiện tại
  const handleDragStart = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    setIsDragging(true);
    dragStart.current = { x: clientX, y: clientY, initialX: cropBox.x, initialY: cropBox.y, containerRect: containerRef.current!.getBoundingClientRect() };
  };

  // Bắt đầu thay đổi kích thước từ handle
  const handleResizeStart = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    setIsResizing(true);
    dragStart.current = { x: clientX, y: clientY, initialX: cropBox.w, initialY: cropBox.h, containerRect: containerRef.current!.getBoundingClientRect() };
  };

  // Bắt đầu VẼ khung mới từ bất kỳ đâu trên container
  const handleContainerMouseDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (isDragging || isResizing) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    const rect = containerRef.current!.getBoundingClientRect();

    const startX = ((clientX - rect.left) / rect.width) * 100;
    const startY = ((clientY - rect.top) / rect.height) * 100;

    setIsDrawing(true);
    setCropBox({ x: startX, y: startY, w: 0, h: 0 });
    dragStart.current = { x: clientX, y: clientY, initialX: startX, initialY: startY, containerRect: rect };
  };

  const handleMove = useCallback((e: MouseEvent | TouchEvent) => {
    if (!isDragging && !isResizing && !isDrawing) return;
    if (!containerRef.current || !imgRef.current) return;

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    const rect = dragStart.current.containerRect;

    const deltaX = ((clientX - dragStart.current.x) / rect.width) * 100;
    const deltaY = ((clientY - dragStart.current.y) / rect.height) * 100;
    const imgRatio = imgRef.current.width / imgRef.current.height;

    if (isDragging) {
      let newX = Math.max(0, Math.min(dragStart.current.initialX + deltaX, 100 - cropBox.w));
      let newY = Math.max(0, Math.min(dragStart.current.initialY + deltaY, 100 - cropBox.h));
      setCropBox(prev => ({ ...prev, x: newX, y: newY }));
    } 
    else if (isResizing) {
      let newW = Math.max(10, Math.min(dragStart.current.initialX + deltaX, 100 - cropBox.x));
      let newH = (newW / aspectRatio) * imgRatio;

      if (cropBox.y + newH > 100) {
        newH = 100 - cropBox.y;
        newW = (newH * aspectRatio) / imgRatio;
      }
      setCropBox(prev => ({ ...prev, w: newW, h: newH }));
    }
    else if (isDrawing) {
      // Logic vẽ khung mới (giữ tỷ lệ từ điểm bắt đầu)
      let newW = deltaX;
      let newH = (newW / aspectRatio) * imgRatio;

      // Xử lý vẽ ngược (từ phải sang trái hoặc dưới lên trên)
      const absW = Math.abs(newW);
      const absH = Math.abs(newH);
      const drawX = newW > 0 ? dragStart.current.initialX : dragStart.current.initialX - absW;
      const drawY = newH > 0 ? dragStart.current.initialY : dragStart.current.initialY - absH;

      // Giới hạn trong khung ảnh
      const finalX = Math.max(0, Math.min(drawX, 100 - absW));
      const finalY = Math.max(0, Math.min(drawY, 100 - absH));

      setCropBox({ x: finalX, y: finalY, w: absW, h: absH });
    }
  }, [isDragging, isResizing, isDrawing, aspectRatio, cropBox.w, cropBox.h]);

  const handleEnd = useCallback(() => {
    setIsDragging(false);
    setIsResizing(false);
    setIsDrawing(false);
  }, []);

  useEffect(() => {
    window.addEventListener('mousemove', handleMove);
    window.addEventListener('mouseup', handleEnd);
    window.addEventListener('touchmove', handleMove);
    window.addEventListener('touchend', handleEnd);
    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [handleMove, handleEnd]);

  const executeCrop = () => {
    if (!imgRef.current || cropBox.w < 5) return;
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = imgRef.current;
    const realW = img.naturalWidth;
    const realH = img.naturalHeight;

    const cropX = (cropBox.x / 100) * realW;
    const cropY = (cropBox.y / 100) * realH;
    const cropW = (cropBox.w / 100) * realW;
    const cropH = (cropBox.h / 100) * realH;

    canvas.width = cropW;
    canvas.height = cropH;
    ctx.drawImage(img, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH);

    onCrop(canvas.toDataURL('image/jpeg', 1.0));
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black/95 backdrop-blur-2xl flex flex-col items-center justify-center p-4 font-sans select-none">
      <div className="w-full max-w-2xl flex flex-col gap-6">
        <div className="flex justify-between items-end text-white border-b border-white/10 pb-4">
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tight flex items-center gap-2">
              <span className="text-brand-500">✂️</span>
              {language === 'vi' ? 'Tự vẽ khung cắt' : 'Draw Crop Area'}
            </h2>
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-1">
              {language === 'vi' ? 'Nhấn và kéo trên ảnh để tạo khung mới' : 'Click and drag on the image to create a new frame'}
            </p>
          </div>
          <button onClick={onCancel} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
          </button>
        </div>

        <div 
          ref={containerRef}
          onMouseDown={handleContainerMouseDown}
          onTouchStart={handleContainerMouseDown}
          className="relative bg-black rounded-2xl overflow-hidden border-2 border-white/10 mx-auto touch-none shadow-2xl cursor-crosshair"
          style={{ maxWidth: '100%', maxHeight: '65vh' }}
        >
          <img 
            ref={imgRef}
            src={imageSrc} 
            className="block max-w-full h-auto opacity-40 grayscale" 
            onLoad={() => setImgLoaded(true)}
            onDragStart={(e) => e.preventDefault()}
          />

          {imgLoaded && cropBox.w > 0 && (
            <div 
              className="absolute border-2 border-brand-500 shadow-[0_0_30px_rgba(59,130,246,0.4)] cursor-move"
              style={{
                left: `${cropBox.x}%`,
                top: `${cropBox.y}%`,
                width: `${cropBox.w}%`,
                height: `${cropBox.h}%`,
                backgroundImage: `url(${imageSrc})`,
                backgroundPosition: `${(cropBox.x / (100 - cropBox.w)) * 100}% ${(cropBox.y / (100 - cropBox.h)) * 100}%`,
                backgroundSize: `${100 / (cropBox.w / 100)}% ${100 / (cropBox.h / 100)}%`,
                backgroundRepeat: 'no-repeat'
              }}
              onMouseDown={handleDragStart}
              onTouchStart={handleDragStart}
            >
              {/* Rules of Thirds */}
              <div className="absolute inset-0 pointer-events-none grid grid-cols-3 grid-rows-3 opacity-20">
                <div className="border-r border-b border-white"></div>
                <div className="border-r border-b border-white"></div>
                <div className="border-b border-white"></div>
                <div className="border-r border-b border-white"></div>
                <div className="border-r border-b border-white"></div>
                <div className="border-b border-white"></div>
                <div className="border-r border-white"></div>
                <div className="border-r border-white"></div>
                <div></div>
              </div>

              {/* ID Photo Silhouette Guide */}
              <div className="absolute inset-0 pointer-events-none flex items-center justify-center opacity-40">
                <svg viewBox="0 0 100 133" className="w-[85%] h-[85%] text-white fill-none stroke-current" strokeWidth="1" strokeDasharray="2 2">
                  <ellipse cx="50" cy="40" rx="25" ry="32" />
                  <path d="M20 120 Q20 80 50 80 Q80 80 80 120" />
                  <line x1="50" y1="0" x2="50" y2="133" strokeWidth="0.5" />
                  <line x1="0" y1="40" x2="100" y2="40" strokeWidth="0.5" />
                </svg>
              </div>

              {/* Resize Handle */}
              <div 
                className="absolute bottom-[-12px] right-[-12px] w-8 h-8 bg-brand-500 rounded-full border-4 border-white cursor-nwse-resize flex items-center justify-center shadow-xl hover:scale-110 transition-transform"
                onMouseDown={handleResizeStart}
                onTouchStart={handleResizeStart}
              >
                <div className="w-2 h-2 border-r-2 border-b-2 border-white transform rotate-45 mb-0.5 mr-0.5"></div>
              </div>
            </div>
          )}

          {isDrawing && (
             <div className="absolute inset-0 pointer-events-none bg-brand-500/5 border border-brand-500/20"></div>
          )}
        </div>

        <div className="flex gap-4">
          <button onClick={onCancel} className="flex-1 py-4 bg-gray-800 hover:bg-gray-700 text-white rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95 transition-all">
            {language === 'vi' ? 'Hủy bỏ' : 'Cancel'}
          </button>
          <button 
            onClick={executeCrop} 
            disabled={cropBox.w < 5}
            className="flex-[2] py-4 bg-brand-600 hover:bg-brand-700 disabled:bg-gray-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-brand-500/40 active:scale-95 transition-all flex items-center justify-center gap-3"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
            {language === 'vi' ? 'Xác nhận Cắt' : 'Confirm Crop'}
          </button>
        </div>

        <div className="text-center">
            <p className="text-[10px] text-gray-500 font-medium italic">
              {language === 'vi' ? '* Nhấn bất kỳ đâu trên ảnh để vẽ lại khung mới.' : '* Click anywhere on the photo to redraw the frame.'}
            </p>
        </div>
      </div>
    </div>
  );
};

