  const initDefaultBox = useCallback(() => {
    if (!imgRef.current) return;
    const imgRatio = imgRef.current.width / imgRef.current.height;
    let w = 60; // 60% chiều rộng
    let h = (w / aspectRatio) * imgRatio;

    if (h > 80) {
      h = 80;
      w = (h * aspectRatio) / imgRatio;
    }

    setCropBox({ x: (100 - w) / 2, y: (100 - h) / 2, w, h });
  }, [aspectRatio]);

  useEffect(() => {
    if (imgLoaded) initDefaultBox();
  }, [imgLoaded, initDefaultBox]);

  // Thao tác Di chuyển khung hiện tại
